const nodemailer = require("nodemailer");

// ─── Configuration ──────────────────────────────────────────────────────────
// Set these via environment variables or edit the defaults below.
const SMTP_HOST = process.env.SMTP_HOST || "smtp.example.com";
const SMTP_PORT = parseInt(process.env.SMTP_PORT || "587", 10);
const SMTP_USER = process.env.SMTP_USER || "you@example.com";
const SMTP_PASS = process.env.SMTP_PASS || "your-password";
const FROM_ADDR = process.env.FROM_ADDR || SMTP_USER;
const TO_ADDR = process.env.TO_ADDR || "bob@example.com";

// ─── Email content ──────────────────────────────────────────────────────────
const subject = "Order Summary — order_summary.xlsx (2026-09-02 to 2026-09-04)";

const textBody = `
Order Summary — order_summary.xlsx
====================================

Period: 2026-09-02 to 2026-09-04
Total Orders: 27
Total Revenue: $1,887

BY STATUS
---------
  Confirmed: 24 orders — $1,701
  Cancelled:  3 orders — $186

TOP CUSTOMERS (confirmed orders only)
--------------------------------------
  1. Maya Chen         — 5 orders, $477
  2. Evan Parker       — 4 orders, $276
  3. Alicia Morgan     — 2 orders, $137
  4. Sofia Ramirez     — 1 order,  $120
  5. Nina Patel        — 1 order,  $62

MOST POPULAR PRODUCTS
---------------------
  • LogiTech Wireless Mouse M310         — 14 orders
  • OXO SoftWorks 3-Piece Mixing Bowl Set — 7 orders
  • Everyday Canvas Tote Bag              — 5 orders
  • Bamboo Desk Organizer Set             — 5 orders
  • Levi's Classic Cotton T-Shirt         — 4 orders
  • Northline Wool Blend Throw Blanket    — 4 orders

KEY OBSERVATIONS
----------------
  • All orders fall on just two dates (Sep 2 and Sep 4, 2026).
  • Average confirmed order value: ~$70.88.
  • Maya Chen is the most active customer (7 total orders; 5 confirmed, 2 cancelled).
  • 8 orders came from anonymised user IDs (e.g. user_2f384bdb).
`;

const htmlBody = `
