  <table>
    <tr><th>#</th><th>Customer</th><th>Orders</th><th>Total Paid</th></tr>
    <tr><td>1</td><td>Maya Chen</td><td>5</td><td>$477</td></tr>
    <tr><td>2</td><td>Evan Parker</td><td>4</td><td>$276</td></tr>
    <tr><td>3</td><td>Alicia Morgan</td><td>2</td><td>$137</td></tr>
    <tr><td>4</td><td>Sofia Ramirez</td><td>1</td><td>$120</td></tr>
